'use client'
import { cn, createMachine, useMachine, useSignals } from '@cascivo/core'
import { forwardRef } from 'react'
import type { ButtonHTMLAttributes } from 'react'
import styles from './toggle.module.css'

export interface ToggleProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange'> {
  /**
   * Invisible accessible name, for when a visible element outside this component already
   * labels it (a heading in a settings row, a table column header) and `label` would render
   * that text a second time.
   *
   * `label` on this component is **visible** — it is painted next to the control. The catalog
   * splits that way deliberately, but `IconButton.label` and `Sparkline.label` are invisible
   * names, so an adopter arriving with that prior writes `label` here and gets the text twice
   * (2026-08-22 report item 13). Both props are now listed side by side, each saying which it
   * is, which is the only thing that interrupts a confident wrong guess.
   *
   * The raw DOM `aria-label` is still accepted and wins over this.
   */
  ariaLabel?: string
  checked?: boolean
  /**
   * Whether the control is checked on first render (uncontrolled).
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  defaultChecked?: boolean
  /** Called with the new checked state when the switch is toggled. */
  onValueChange?: (checked: boolean) => void
  /**
   * Renders a **visible** text label beside the switch that also becomes its
   * accessible name. When a visible heading already labels the control, omit
   * `label` (it would duplicate that text) and pass `aria-label` instead —
   * `aria-label` is forwarded to the underlying button.
   */
  label?: string
  size?: 'sm' | 'md'
}

/**
 * `forwardRef` so `ref` reaches the underlying `<button>` — and so it is TYPED. See
 * `textarea.tsx` for the full rationale (2026-07-28 report C10). `forwardRef` rather than a
 * bare `ref?: Ref<T>` prop keeps the `react >= 18` peer floor honest, since ref-as-prop does
 * not work there.
 */
export const Toggle = forwardRef<HTMLButtonElement, ToggleProps>(function Toggle(
  {
    checked,
    defaultChecked = false,
    onValueChange,
    label,
    size = 'md',
    className,
    disabled,
    ariaLabel,
    ...props
  },
  ref,
) {
  useSignals()
  const machine = createMachine({
    initial: defaultChecked ? ('on' as const) : ('off' as const),
    states: {
      off: { on: { TOGGLE: 'on' } },
      on: { on: { TOGGLE: 'off' } },
    },
  })
  const [state, send] = useMachine(machine)

  const isControlled = checked !== undefined
  const isOn = isControlled ? checked : state.value === 'on'

  const handleClick = () => {
    if (!isControlled) send('TOGGLE')
    onValueChange?.(!isOn)
  }

  return (
    <button
      type="button"
      role="switch"
      aria-checked={isOn}
      data-state={isOn ? 'on' : 'off'}
      data-size={size}
      disabled={disabled}
      className={cn(styles['toggle'], className)}
      onClick={handleClick}
      ref={ref as never}
      {...props}
      aria-label={props['aria-label'] ?? ariaLabel}
    >
      <span className={styles['track']} aria-hidden="true">
        <span className={styles['thumb']} />
      </span>
      {label && <span className={styles['label']}>{label}</span>}
    </button>
  )
})

@layer cascivo.component {
  .toggle {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    padding: 0;
    background: none;
    border: none;
    font-family: var(--cascivo-font-sans);
    cursor: pointer;

    &[data-size='sm'] {
      --_track-w: 1.75rem;
      --_track-h: 1rem;
      --_thumb: 0.75rem;
    }
    &[data-size='md'] {
      --_track-w: 2.25rem;
      --_track-h: 1.25rem;
      --_thumb: 1rem;
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    &:focus-visible {
      outline: none;
    }
  }

  .track {
    display: inline-flex;
    align-items: center;
    flex-shrink: 0;
    inline-size: var(--_track-w);
    block-size: var(--_track-h);
    padding: 2px;
    border-radius: var(--cascivo-radius-full);
    background-color: var(--cascivo-color-border-strong);
    transition: background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    .toggle[data-state='on'] & {
      background-color: var(--cascivo-color-accent);
    }

    .toggle:focus-visible & {
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  .thumb {
    inline-size: var(--_thumb);
    block-size: var(--_thumb);
    border-radius: var(--cascivo-radius-full);
    background-color: var(--cascivo-color-surface);
    box-shadow: var(--cascivo-shadow-sm);
    transition: translate var(--cascivo-duration-150) var(--cascivo-ease-out);

    .toggle[data-state='on'] & {
      translate: calc(var(--_track-w) - var(--_thumb) - 4px) 0;
    }
  }

  .label {
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    line-height: var(--cascivo-leading-snug);
  }

  /* Coarse-pointer touch targets — raise minimum to 44px, desktop density unchanged */
  @media (pointer: coarse) {
    .toggle {
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }
  }
}

@media (forced-colors: active) {
  .track {
    border: 1px solid ButtonText;
  }

  .toggle[data-state='on'] .track {
    border-color: Highlight;
    background-color: Highlight;
  }

  .toggle:focus-visible .track {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Toggle',
  description: 'On/off switch built as an accessible button',
  category: 'inputs',
  clientJs: 'enhancement',
  states: ['off', 'on'],
  variants: [],
  sizes: ['sm', 'md'],
  props: [
    {
      name: 'checked',
      description: 'Whether the control is checked (controlled).',
      type: 'boolean',
      required: false,
    },
    {
      name: 'defaultChecked',
      description: 'Whether the control is checked on first render (uncontrolled).',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'onValueChange',
      description: 'Called with the new checked state when the switch is toggled.',
      type: '(checked: boolean) => void',
      required: false,
    },
    {
      name: 'label',
      nameVisibility: 'visible',
      description:
        'Visible text label beside the switch; it also becomes the accessible name. When a heading already labels the control, omit this and pass aria-label instead to avoid duplicated text.',
      type: 'string',
      required: false,
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md'",
      required: false,
      default: 'md',
    },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'ariaLabel',
      description:
        'Invisible accessible name, for when a visible element outside this component already labels it and `label` would render that text a second time. ⚠ `label` on this component is **visible**; `IconButton.label`/`Sparkline.label` are invisible names, which is the prior that costs adopters a duplicated label. The raw DOM `aria-label` still wins over this.',
      type: 'string',
      required: false,
      nameVisibility: 'invisible',
    },
  ],
  tokens: [
    '--cascivo-color-accent',
    '--cascivo-color-border-strong',
    '--cascivo-color-surface',
    '--cascivo-radius-full',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'switch',
    wcag: '2.2-AA',
    keyboard: ['Space', 'Enter'],
    apgPattern: 'switch',
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    { title: 'Uncontrolled', code: '<Toggle label="Notifications" defaultChecked />' },
    {
      title: 'Controlled',
      code: '<Toggle checked={enabled} onValueChange={setEnabled} label="Dark mode" />',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['switch', 'form', 'boolean'],
  intent: {
    whenToUse: [
      'Flipping a single binary setting that takes effect immediately (e.g. notifications on/off)',
      'On/off state where a physical switch metaphor reads better than a checkmark',
      'Settings screens where the change applies live without a separate submit',
    ],
    whenNotToUse: [
      'Selecting items in a form that is submitted later — use Checkbox',
      'Choosing one option among several mutually exclusive labels — use SegmentedControl or Radio',
    ],
    antiPatterns: [
      {
        bad: '<Toggle label="I accept the terms" /> inside a submitted form',
        good: '<Checkbox label="I accept the terms" />',
        why: 'A switch implies an instant on/off setting; agreement that is submitted with the form is a checkbox',
      },
      {
        bad: '<h3>Dark mode</h3><Toggle label="Dark mode" /> — the label repeats the heading',
        good: '<h3>Dark mode</h3><Toggle aria-label="Dark mode" />',
        why: 'The `label` prop renders visible text and is the accessible name; when a heading already names the control, use aria-label so the name is not shown (and read) twice',
      },
    ],
    related: [
      {
        name: 'Checkbox',
        relationship: 'alternative',
        reason: 'Use for form selections submitted later rather than instant settings',
      },
      {
        name: 'SegmentedControl',
        relationship: 'alternative',
        reason: 'Use when choosing among several exclusive options, not just on/off',
      },
    ],
    a11yRationale:
      'Renders a <button role="switch"> with aria-checked reflecting state, so assistive tech announces it as a switch and Space/Enter toggle it via native button activation.',
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Track and thumb colors must resolve to --cascivo-color-* / radius / focus-ring tokens',
      },
      {
        area: 'label copy',
        level: 'flexible',
        note: 'Optional label describing the setting being toggled',
      },
    ],
  },
}
